class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if not self.is_empty():
            return self.items.pop()

    def peek(self):
        if not self.is_empty():
            return self.items[-1]

    def is_empty(self):
        return len(self.items) == 0

    def size(self):
        return len(self.items)


def precedence(op):
    if op == '+' or op == '-':
        return 1
    if op == '*' or op == '/':
        return 2
    return 0


def infix_to_postfix(infix_expr):
    postfix_expr = ''
    operators_stack = Stack()

    for token in infix_expr:
        if token.isalnum():
            postfix_expr += token +''
        elif token == '(':
            operators_stack.push(token)
        elif token == ')':
            while not operators_stack.is_empty() and operators_stack.peek()!= '(':
                op = operators_stack.pop()
                postfix_expr += op +''
            if not operators_stack.is_empty() and operators_stack.peek()!= '(':
                raise Exception("Mismatched parentheses")
            operators_stack.pop()
        else:
            while (not operators_stack.is_empty() and
                   precedence(operators_stack.peek()) >= precedence(token)):
                postfix_expr += operators_stack.pop() +''
            operators_stack.push(token)

    while not operators_stack.is_empty():
        postfix_expr += operators_stack.pop() +''

    return postfix_expr


if __name__ == "__main__":
    infix_expr = input("Enter an Infix expression: ")
    try:
        postfix_expr = infix_to_postfix(infix_expr)
        print(f"Postfix expression: {postfix_expr}")
    except Exception as e:
        print(f"Error: {e}")
```
