class Node:
    """A node in a binary search tree."""

    def __init__(self, key):
        """Initializes a new node with the given key.

        Args:
            key: The key to store in the node.
        """
        self.key = key
        self.left = None
        self.right = None


class BinarySearchTree:
    """A binary search tree."""

    def __init__(self):
        """Initializes a new binary search tree."""
        self.root = None

    def insert(self, key):
        """Inserts a new key into the tree.

        Args:
            key: The key to insert.
        """
        if self.root is None:
            self.root = Node(key)
        else:
            self._insert_recursive(self.root, key)

    def _insert_recursive(self, node, key):
        """A helper function for inserting a key recursively.

        Args:
            node: The current node.
            key: The key to insert.
        """
        if key < node.key:
            if node.left is None:
                node.left = Node(key)
            else:
                self._insert_recursive(node.left, key)
        elif key > node.key:
            if node.right is None:
                node.right = Node(key)
            else:
                self._insert_recursive(node.right, key)

    def search(self, key):
        """Searches for a key in the tree.

        Args:
            key: The key to search for.

        Returns:
            True if the key is found, False otherwise.
        """
        return self._search_recursive(self.root, key)

    def _search_recursive(self, node, key):
        """A helper function for searching a key recursively.

        Args:
            node: The current node.
            key: The key to search for.

        Returns:
            True if the key is found, False otherwise.
        """
        if node is None or node.key == key:
            return node is not None

        if key < node.key:
            return self._search_recursive(node.left, key)

        return self._search_recursive(node.right, key)
