```python
def is_valid(grid, row, col, num):
    """Check if a number is valid in a given cell"""
    for x in range(9):
        if grid[row][x] == num or grid[x][col] == num:
            return False
    start_row = row - row % 3
    start_col = col - col % 3
    for i in range(3):
        for j in range(3):
            if grid[i + start_row][j + start_col] == num:
                return False
    return True


def solve_sudoku(grid, row=0, col=0):
    """Solve a Sudoku puzzle using a backtracking algorithm"""
    if row == 9 - 1 and col == 9:
        return True

    if col == 9:
        row += 1
        col = 0

    if grid[row][col] > 0:
        return solve_sudoku(grid, row, col + 1)

    for num in range(1, 10):
        if is_valid(grid, row, col, num):
            grid[row][col] = num
            if solve_sudoku(grid, row, col + 1):
                return True
        grid[row][col] = 0

    return False

# Example usage
