import Foundation

func randomString(ofLength n: Int) -> String {
    let allowedChars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
    var randomString = ""
    for _ in 0..<n {
        let randomIndex = Int(arc4random_uniform(allowedChars.count))
        randomString.append(allowedChars[allowedChars.index(allowedChars.startIndex, offsetBy: randomIndex)])
    }
    return randomString
}

