class CaveGame:
    """
    A simple text-based game where the user explores a cave and collects coins.
    """

    def __init__(self):
        """
        Initializes the cave game with a set of coordinates for the location of the coins.
        """
        self.coins = [(5, 5), (10, 2), (3, 8)]

    def play(self):
        """
        Starts the game and allows the user to navigate the cave and collect coins.
        """
        print("Welcome to the Cave Adventure!")
        current_location = (1, 1)  # Start location
        while True:
            self.display_map(current_location)
            direction = self.get_user_direction()
            if direction == "quit":
                break
            new_location = self.move(current_location, direction)
            if new_location in self.coins:
                print(f"Congratulations! You found a coin at {new_location}!")
                self.coins.remove(new_location)
            current_location = new_location
        if self.coins:
            print("You found the following coins, but they were not enough to complete the game:")
            for coin in self.coins:
                print(f"Coin at {coin}")
        else:
            print("You found all the coins! You win!")

    def get_user_direction(self):
        """
        Asks the user for a direction to move in and validates the input.
        Returns 'quit' if the user wants to exit the game.
        """
        while True:
            direction = input("Where do you want to go? (n/s/e/w/q) ").lower()
            if direction in ["n", "s", "e", "w", "q"]:
                return direction
            else:
                print("Invalid direction. Please try again.")

    def move(self, current_location, direction):
        """
        Calculates the new location based on the current location and the direction.
        """
        x, y = current_location
        if direction == "n":
            return x, y - 1
        elif direction == "s":
            return x, y + 1
        elif direction == "e":
            return x + 1, y
        elif direction == "w":
            return x - 1, y

    def display_map(self, current_location):
        """
        Displays the cave map with the user's current location and the locations of the remaining coins.
        """
        map_str = ""
        x, y = current_location
        for i in range(1, 11):
            for j in range(1, 11):
                if (i, j) == current_location:
                    map_str += "| "
                elif (i, j) in self.coins:
                    map_str += "C "
                else:
                    map_str += "."
            map_str += "|"
            if i % 2 == 0:
                map_str += "\n"
        print(map_str)

if __name__ == "__main__":
    game = CaveGame()
    game.play()
```

In this game, the player starts at the location (1,1) and can navigate using the cardinal directions (north, south, east, west). The player can also quit the game by typing 'q'. The game ends when all the coins are collected or when the player decides to quit. The game map is displayed after each move, showing the current location and the locations of the remaining coins. The map is updated every time the player moves. The game also checks if the player collects a coin and updates the list of available coins. The game ends when all the coins are collected, displaying a win message.

