def get_nested_value(dictionary, keys):
    """
    This function takes a dictionary and a list of keys as input and returns the value
    associated with the last key in the list if it exists, otherwise it returns None.

    Args:
        dictionary (dict): The dictionary to search for the value.
        keys (list): A list of keys to traverse the dictionary.

    Returns:
        Any: The value associated with the last key in the list if it exists, otherwise None.
    """
    current_level = dictionary
    for key in keys[:-1]:
        if key in current_level:
            current_level = current_level[key]
        else:
            return None

    if keys[-1] in current_level:
        return current_level[keys[-1]]
    else:
        return None

